package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFile *os.File
var amtReader *bufio.Reader
var curRec AmtRec
var pendingEOF bool
var limit5 = decimal.NewFromInt(100000)

func isInputDone() bool { return WsEofFlag == "Y" }

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func dropHighDigits(d decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	modInt := decimal.NewFromInt(1)
	for i := int32(0); i < intDigits; i++ {
		modInt = modInt.Mul(decimal.NewFromInt(10))
	}
	if d.Abs().GreaterThanOrEqual(modInt) {
		q := d.Div(modInt).Truncate(0)
		d = d.Sub(q.Mul(modInt))
		if d.IsNegative() {
			d = d.Add(modInt)
		}
	}
	return d.Truncate(scale)
}

func storeBigTotal(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	v = dropHighDigits(v, 7, 2)
	WsBigTotal = v
}
func storeWrapTotal(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	v = dropHighDigits(v, 5, 2)
	WsWrapTotal = v
}
func storeSafeTotal(v decimal.Decimal) {
	v = truncateDecimal(v, 2)
	v = dropHighDigits(v, 5, 2)
	WsSafeTotal = v
}
func storeHalf(v decimal.Decimal) {
	v = truncateDecimal(v, 1)
	v = dropHighDigits(v, 5, 1)
	WsHalf = v
}

func addToBigTotal(amt decimal.Decimal) {
	res := WsBigTotal.Add(amt)
	storeBigTotal(res)
}

func addToSafeTotalWithSizeError(amt decimal.Decimal) bool {
	res := WsSafeTotal.Add(amt)
	resTrunc := truncateDecimal(res, 2)
	if resTrunc.IsNegative() || resTrunc.GreaterThanOrEqual(limit5) {
		return true
	}
	storeSafeTotal(res)
	return false
}

func formatZZZZ9_99(d decimal.Decimal, pic string) string {
	var decPlaces int
	var width int
	if pic == "ZZ,ZZ9.99" {
		decPlaces = 2
		width = 9
	} else {
		decPlaces = 1
		width = 8
	}
	d = truncateDecimal(d, int32(decPlaces))
	intPart := d.Truncate(0)
	// fractional part as integer
	pow := decimal.NewFromInt(1)
	for i := 0; i < decPlaces; i++ {
		pow = pow.Mul(decimal.NewFromInt(10))
	}
	fracInt := d.Sub(intPart).Mul(pow).Truncate(0)
	fracStr := fmt.Sprintf("%0*d", decPlaces, fracInt.IntPart())

	intWidth := width - 1 - decPlaces // 6
	// comma position for width 6 is index 2
	commaPos := 2

	intStr := intPart.String() // e.g. "10000"
	// digits buffer for intWidth including comma slot
	digits := make([]byte, intWidth)
	for i := range digits {
		digits[i] = ' '
	}
	// fill from right skipping comma
	pos := intWidth - 1
	idx := len(intStr) - 1
	for pos >= 0 {
		if pos == commaPos {
			digits[pos] = ','
			pos--
			continue
		}
		if idx >= 0 {
			digits[pos] = intStr[idx]
			idx--
		} else {
			digits[pos] = '0'
		}
		pos--
	}
	// Z suppression: replace leading zeros and comma in suppressed zone with spaces
	// Find position of first non-zero digit (ignoring comma)
	firstNonZero := -1
	for i := 0; i < intWidth; i++ {
		if i == commaPos {
			continue
		}
		if digits[i] != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zeros -> only last digit '0' kept
		for i := 0; i < intWidth; i++ {
			if i == commaPos {
				digits[i] = ' '
			} else if i == intWidth-1 {
				digits[i] = '0'
			} else {
				digits[i] = ' '
			}
		}
	} else {
		for i := 0; i < firstNonZero; i++ {
			digits[i] = ' '
		}
		// if first non-zero is after comma, comma was in suppressed zone -> already set to space in loop above
		// need to handle case where comma is in suppressed zone vs not
		// The loop above blanks everything before firstNonZero including comma if comma < firstNonZero
		// So nothing else to do
	}
	intField := string(digits)
	return intField + "." + fracStr
}

func parseAmtRecLine(line string) AmtRec {
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	if len(line) > 11 {
		line = line[:11]
	}
	acct := line[0:4]
	amtStr := line[4:11]
	var n int64
	for _, ch := range amtStr {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	amt := decimal.New(n, -2)
	return AmtRec{ArAcct: acct, ArAmt: amt}
}

func READ_PARA() {
	line, err := amtReader.ReadString('\n')
	if err != nil {
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		line = strings.TrimRight(line, "\r\n")
		curRec = parseAmtRecLine(line)
		WsEofFlag = "N"
		pendingEOF = true
		return
	}
	line = strings.TrimRight(line, "\r\n")
	curRec = parseAmtRecLine(line)
	WsEofFlag = "N"
}

func READ_PARA_WRAPPER() {
	if pendingEOF {
		pendingEOF = false
		WsEofFlag = "Y"
		return
	}
	READ_PARA()
}

func OVERFLOW_PARA() {
	WsOverflows += 1
}

func PROCESS_PARA() {
	addToBigTotal(curRec.ArAmt)
	storeWrapTotal(WsBigTotal)

	overflow := addToSafeTotalWithSizeError(curRec.ArAmt)
	if overflow {
		OVERFLOW_PARA()
	}
	// The following statements are NOT part of ON SIZE ERROR - they always execute
	// (The ambiguous ADD ... END-ADD scope bug is that only OVERFLOW-PARA is conditional)
	WsCount += 1
	halfRaw := curRec.ArAmt.Div(decimal.NewFromInt(2))
	storeHalf(halfRaw)

	WsAmtEd = formatZZZZ9_99(curRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatZZZZ9_99(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatZZZZ9_99(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatZZZZ9_99(WsHalf, "ZZ,ZZ9.9")

	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	READ_PARA_WRAPPER()
}

func SUMMARY_PARA() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func MAIN_PARA() {
	var err error
	amtFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer amtFile.Close()
	amtReader = bufio.NewReader(amtFile)
	READ_PARA_WRAPPER()
	for !isInputDone() {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}

func main() {
	MAIN_PARA()
}
